      titulo: "Legislação Tributária",
      conteudo: `10.1. Espécies
A expressão Legislação Tributária aparece no segundo livro do Código Tributário Naci-
onal como Gênero que se divide nas seguintes espécies: Leis, Tratados e Convenções Inter-
nacionais, Decretos e as Normas Complementares (art. 96, CTN).
No momento da prova, lembre-se:
Legislação Tributária é a “LETRA DE NORMAS”
Em que:
LE – Representa as “Leis”
TRA – Representa os “Tratados e Convenções Internacionais”
DE – Representa os “Decretos”
NORMAS – Representa as “Normas Complementares”
Analisemos os principais aspectos dessas espécies:
a) Leis (art. 97, CTN): Considerada regra geral no direito tributário, a maioria das
matérias estarão reservadas à edição de lei (Princípio da legalidade tributária).
Assim, dependem da edição de lei: instituição, extinção, majoração ou redução de
tributos, definição dos fatos geradores das obrigações tributárias principais, fixação
de alíquotas e bases de cálculo, a cominação de penalidades em infrações come-
tidas, as hipóteses de exclusão, suspensão e extinção de créditos tributários, ou de
dispensa ou redução de penalidades.
Ressalte-se, ainda, o rol de matérias tributárias que necessitam da edição de Lei
Complementar, aprovadas pela maioria absoluta (art. 146, CF):`
