      num: 1,
      titulo: "Débitos de obrigação própria e responsáveis (inciso I) A autoridade inicial-",
      conteudo: `mente deverá verificar quais débitos o devedor pagará na condição de Contri-
buinte (obrigação própria), para posteriormente quitar aqueles em que figura
como Responsável Tributário. Se em todos os débitos estiver atuando o de-
vedor como contribuinte, o próximo critério será utilizado.`
